              : "bg-ht-cyan-500/25 dark:bg-ht-cyan-400/20"
          )}
          style={pending ? undefined : { width: `${percent}%` }}
        />
        <span
          className={cn(
            "absolute inset-y-0 right-2.5 flex items-center font-mono text-xs",
            pending
              ? "text-muted-foreground"
              : "text-ht-cyan-800/85 dark:text-ht-cyan-300/85"
