    },
    loading: { detail: STEP_TWO_DETAIL, label: STEP_TWO_LABEL, mark: "2" },
    parts: { detail: STEP_THREE_DETAIL, label: STEP_THREE_LABEL, mark: "3" },
  };

/** The mono step marker inside a deck button — real sequence, so real numbers. */
