async () => {
  const fig = document.querySelector('figure');
  const btn = (t) => [...fig.querySelectorAll('button')].find(b => b.textContent.includes(t));
  const sleep = (ms) => new Promise(r => setTimeout(r, ms));
  const seam = () => [...fig.querySelectorAll('[role=status] span')].filter(s => !s.className.includes('invisible')).map(s => s.textContent);
  const out = { blocking: seam() };
  btn('Add a fallback').click(); await sleep(2400);
  out.loading = seam();
  btn('Wrap each part').click(); await sleep(2400);
  out.parts = seam();
  out.chrome = fig.querySelector('figcaption').innerText.replace(/\n+/g, ' | ');
  return out;
}

